        "function std_format_to_n<It>(out: It, n: number, fmt: string, ...args: any[]): { out: It; size: number } { const buf = { s: '' }; __fmt_into(buf, fmt, args); const total = buf.s.length; const trimmed = n < 0 ? '' : buf.s.slice(0, n); __fmt_writeIter(out, trimmed); return { out, size: total }; }",
        "function std_formatted_size(fmt: string, ...args: any[]): number { const out = { s: '' }; __fmt_into(out, fmt, args); return out.s.length; }",
        "class std_formatter<T> { spec: string = ''; parse(spec: string): void { this.spec = spec; } format(value: T): string { const nidx = { value: 0 }; return __fmt_value(value, this.spec, [], nidx); } }",
