        "  if (Array.isArray(match)) { match.length = 0; m.forEach((s, i) => match[i] = { str: () => s, toString: () => s }); }",
        "  return true;",
        "}",
        "function regex_match(text: any, ...rest: any[]): boolean {",
        "  const args = rest.map(__rx_unbox).filter(a => !(typeof a === 'number'));",
