        "  let idx = 0;",
        "  const view: any = {",
        "    get __done() { return idx >= matches.length; },",
        "    get __matches() { return matches; },",
        "    get __idx() { return idx; },",
        "    str(g: number = 0) { const m = matches[idx]; return (m && m[g]) != null ? m[g] : ''; },",
        "    __advance() { idx++; return this; },",
