        const dm = line.match(declSplitRe);
        if (!dm) { splitDecls.push(line); continue; }
        const [, declHead, varName, initExpr] = dm;
        // Detect class-reference in the initializer. A class reference is any
        // `new Foo(` / `new Foo<` / `new Foo \n` occurrence where `Foo` is in
        // the classNames set. We also conservatively split if the initializer
        // uses `Object.assign(new X` — that's the dominant pattern.
        let referencesDeferred = false;
        if (/\bnew\s+([A-Za-z_$][\w$]*)/.test(initExpr)) {
          const newRe = /\bnew\s+([A-Za-z_$][\w$]*)/g;
          let mm: RegExpExecArray | null;
          while ((mm = newRe.exec(initExpr)) !== null) {
            if (classNames.has(mm[1])) { referencesDeferred = true; break; }
          }
        }
        // ATOM-L8: defer init to postamble if it references any TDZ-sensitive
        // binding — a let/const declared in this module body, or a name that
        // came in via an import (possibly through a cyclic import graph).
        // Scan identifiers in initExpr, excluding property accesses (tokens
        // preceded by `.`) and excluding the declared name itself.
        if (!referencesDeferred) {
          const identRe = /(?<![.\w$])([A-Za-z_$][\w$]*)/g;
          let im: RegExpExecArray | null;
          while ((im = identRe.exec(initExpr)) !== null) {
            const id = im[1];
            if (id === varName) continue;
            if (tsReserved.has(id)) continue;
            if (letConstNames.has(id) || importedNames.has(id)) {
              referencesDeferred = true;
              break;
            }
          }
        }
