        splitDecls.push(`${declHead};`);
        // Stage 2: assignment in postamble — runs after classes/let/const
        // decls and after cyclic-import bindings resolve.
        staticPostamble.push(`${varName} = ${initExpr};`);
        // SQL-G20b — mark any referenced local class for hoisting so the
        // postamble assignment can see it at module scope.
        const newRe2 = /\bnew\s+([A-Za-z_$][\w$]*)/g;
        let nm2: RegExpExecArray | null;
        while ((nm2 = newRe2.exec(initExpr)) !== null) {
          const local = localClassesByName.get(nm2[1]);
          if (local && !localClassLineRanges.some(([s,e]) => s === local.startLine)) {
            localClassLineRanges.push([local.startLine, local.endLine]);
          }
        }
