        // others leave it for us to compute from the inner type nodes.
        // Common traits: __builtin_types_compatible_p (C), is_same/is_base_of
        // (C++20 §21.3). The Clang JSON dump does NOT carry the trait's
        // textual name in many versions, so we infer from structure: when
        // there are exactly two type-children, treat as a 2-type-equality
        // trait (correct for both __builtin_types_compatible_p and
        // std::is_same — the most common cases).
        const v = (node as any).value;
        if (v !== undefined) return String(v);
        const types = (node.inner ?? [])
          .filter((c: any) => /Type$/.test(c?.kind ?? ""))
          .map((c: any) => (c.type?.qualType ?? c.qualType ?? "").trim());
        if (types.length === 2) {
          return types[0] === types[1] ? "1" : "0";
        }
