        // coerced to the requested type. The va_list variable appears as the
        // first (and only) child expression; the requested type is in the
        // node's own type.qualType. We route through __va_arg which advances
        // `ap.pos` and applies the integer/float/string coercion the spec
        // requires.
        this.usesVaArg = true;
        const vaChild = (node.inner ?? [])[0];
        const apExpr = vaChild ? this.emitExpr(vaChild) : "ap";
        const rawType = String((node as any).type?.qualType ?? "int");
