        // canonical C spelling so __va_coerce can switch on it.
        const typeHint = rawType
          .replace(/\bstruct\s+/g, "")
          .replace(/\bclass\s+/g, "")
          .replace(/\bvolatile\b/g, "")
          .replace(/\s+/g, " ")
          .trim();
